// Turn the uploaded file into a base64 data URI for the Mistral OCR API.
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const bin = item.binary || {};
  const key = Object.keys(bin)[0];
  if (!key) throw new Error('No binary file on the incoming item.');
  const b = bin[key];
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  const mime = b.mimeType || 'application/pdf';
  out.push({ json: {
    fileName: b.fileName || 'document',
    mimeType: mime,
    dataUri: 'data:' + mime + ';base64,' + buf.toString('base64')
  }});
}
return out;

/* ============ SHARED ============ */

var ORDINAL_WORDS = {
  one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10,
  eleven:11, twelve:12, thirteen:13, fourteen:14, fifteen:15, sixteen:16,
  seventeen:17, eighteen:18, nineteen:19, twenty:20,
  first:1, second:2, third:3, fourth:4, fifth:5, sixth:6, seventh:7, eighth:8,
  ninth:9, tenth:10
};
var ORD_WORD_RE = Object.keys(ORDINAL_WORDS).join('|');

var ROMAN_RE = /^[ivxlcdm]+$/i;

function romanToInt(s) {
  var m = { i:1, v:5, x:10, l:50, c:100, d:500, m:1000 }, t = 0, p = 0, i;
  s = String(s).toLowerCase();
  for (i = s.length - 1; i >= 0; i--) {
    var v = m[s[i]] || 0;
    t += v < p ? -v : v;
    p = Math.max(p, v);
  }
  return t;
}

/* Ordered rank of a marker token: "2" < "2A" < "2B" < "3". markerValue() reads
   only the leading digits, so it cannot separate an inserted section from its
   parent — use this wherever ordering matters. */
function markerRank(tok) {
  if (tok == null) return NaN;
  var t = String(tok).trim().toUpperCase();
  var m = t.match(/^(\d+)([A-Z]{0,3})$/);
  if (m) {
    var r = parseInt(m[1], 10) * 1000, suf = m[2], i;
    for (i = 0; i < suf.length; i++) r += (suf.charCodeAt(i) - 64) * (i === 0 ? 26 : 1);
    return r;
  }
  var v = markerValue(t);
  return isNaN(v) ? NaN : v * 1000;
}

/* numeric value of a marker token, for monotonicity / TOC detection */
function markerValue(tok) {
  if (tok == null) return NaN;
  tok = String(tok).trim();
  var m = tok.match(/^(\d+)/);
  if (m) return parseInt(m[1], 10);
  if (ROMAN_RE.test(tok)) return romanToInt(tok);
  var w = ORDINAL_WORDS[tok.toLowerCase()];
  return w == null ? NaN : w;
}

/* Units / measurement tails that must never open a provision. */
var UNIT_TAIL = '(?:mm|cm|km|kg|kV|kA|kW|MW|MPa|kPa|Hz|MHz|GHz|ms|min|sec|hrs?|%|per\\s?cent|°C|℃|m[²³]?\\b|ft|in\\b|lbs?\\b)';

/* Lines that are pure furniture. */
var NOISE_RES = [
  /^\s*[-–—~]{1,3}\s*\d{1,4}\s*[-–—~]{1,3}\s*$/,          // - 12 -
  /^\s*(?:page\s+)?\d{1,4}\s*(?:of|\/)\s*\d{1,4}\s*$/i,    // 3 of 8 · Page 3/8
  /^\s*page\s+\d{1,4}\s*$/i,
  /^\s*\d{1,4}\s*$/,                                        // bare page number
  /^\s*[ivxlcdm]{1,6}\s*$/i,                                // roman page number
  /^.{1,80}[.·]{4,}\s*\d{1,4}\s*$/,                         // TOC dotted leader
  /^\s*_{3,}\s*$/,
  /^\s*(?:\[\d{1,6}\]|\d{1,6})(?:\s+(?:\[\d{1,6}\]|\d{1,6}))?\s*$/,   // "[283] 7" · "44 [283]"
  /^\s*[A-Z .]{0,40}\s*\d{1,4}\s*\[\d{1,6}\]\s*$/,
  /^\s*\[?\s*(?:this page (?:is )?(?:intentionally )?(?:left )?blank)\s*\]?\s*$/i,
  /^\s*(?:unofficial|informal)\s+translation\s*$/i,
  /^\s*compilation\s+no\.?\s*\d+\s*$/i,
  /^\s*registered\s*:\s*\d/i,
  /^\s*\d{0,3}\s*OJ\s+(?:No\.|L\b|C\b)/,                                   // EU OJ footnote
  /^\s*Notice of the making of this Statutory Instrument was published/i,
  /^\s*(?:GIVEN under my hand|Given under my (?:hand|Official Seal))/i,
  /^\s*THE\s+GAZETTE\s+OF\s+INDIA\b/i,
  /^\s*\[?\s*PART\s+[IVX]+\s*[\u2014-]{0,2}\s*SEC\.?[^\]]*\]?\s*$/i,      // [PART II-SEC. 3(ii)]
  /^\s*\u0939\u093F|^\s*\[\s*\u092D\u093E\u0917/,                            // Hindi gazette banner
  /^\s*\(?(?:Published|To be published) in the Gazette/i
];

/* Dialect-scoped strippers: applied to a whole line, in place. */
var STRIPPERS = {
  /* Hong Kong inline source notes: (Amended 12 of 1999 s. 3) */
  hk_source: /\s*\((?:Amended|Added|Replaced|Repealed|Format changes)[^()]*(?:\([^()]*\)[^()]*)*\)\s*$/g,
  /* UK legislation.gov.uk textual-amendment markers: [F1 …] */
  uk_fmark: /\[?F\d{1,4}\]?/g,
  /* Ireland eISB markers: F5[ … ]F5 */
  ie_fmark: /F\d{1,4}\[|\]F\d{1,4}/g,
  /* South Africa consolidation editorial notes */
  za_edit: /\[[^\]]*?(?:substituted|inserted|added|deleted|amended|repealed|commencement|Sub-s\.|Para\.)[^\]]*?\]/gi,
  /* Canada bilingual consolidations: each English definition ends with the
     French headword in guillemets — "employer" means … ; « employeur » */
  ca_gloss: /\s*[;.]?\s*\u00AB[^\u00BB]{1,120}\u00BB\s*$/,
  /* Canada, Justice Laws: per-section amendment trail printed under the text —
     "R.S., 1985, c. A-1, s. 3; 1992, c. 21, s. 1; 2019, c. 18, s. 3." */
  ca_amend: /^\s*(?:R\.S\.[A-Z.]{0,3},?\s*)?\(?\d{4}\)?(?:-\d{2})?,\s*(?:c|ch)\.\s*[^\s,]+(?:[,;][^;]*)*\.?\s*$/i,
  /* India / SEBI / RBI superscript footnote caller fused to a bracket: 3[ … ] */
  in_bracket_open: /(^|[\s(])(\d{1,3})\[/g,
  in_omitted: /\*{3,}/g,
  /* Editorial asterisk / hash prefixes (HK not-yet-in-operation) */
  hk_flag: /^\s*[*#]+\s*/
};

/* Non-boundary content markers — kept inside `contenu`, used only to
   disambiguate and to repair OCR line merges. */
var RE_SUBSEC   = /^\s*\((\d{1,3}[A-Z]{0,2})\)\s+/;
var RE_PARA_A   = /^\s*\(([a-z]{1,3})\)\s+/;
var RE_PARA_ROM = /^\s*\(([ivxlcdm]{1,8})\)\s+/;
var RE_PARA_CAP = /^\s*\(([A-Z]{1,3})\)\s+/;
var RE_IE_DEG   = /^\s*(\d{1,2})\s*[\u00B0\u00BA\u02DA]\s*(.*)$/;   // Irish 1° 2° 3°

/* Special content blocks (tagged, never boundaries). */
var RE_PROVISO     = /^\s*Provided\s+(?:that|further|also|always)\b/i;
var RE_EXPLANATION = /^\s*Explanation\s*(\d+)?\s*[.:\u2014-]/i;
var RE_ILLUSTR     = /^\s*Illustrations?\s*[.:\u2014-]?\s*$/i;
var RE_NOTE_AU     = /^\s*Note\s*(\d+)?\s*:/i;
/* Victorian / OPC style prints a bare "Note", "Notes" or "Examples" line and
   then numbers the items 1, 2, 3 — which look exactly like section markers. */
var RE_NOTE_BLOCK  = /^\s*(?:Notes?|Examples?)\s*:?\s*$/i;
var RE_PENALTY_AU  = /^\s*(?:Maximum\s+)?Penalt(?:y|ies)\s*:/i;
var RE_REPEALED    = /^\s*\(?(Repealed|Omitted|Deleted|Not yet in operation)\)?\s*\.?\s*$/i;

/* TOC entry / exit. */
/* "Definitions ......... 12" — dot leaders in a table of contents */
var RE_DOT_LEADER = /[.\u00B7\u2024]{3,}\s*\d{1,4}\s*$/;

var RE_TOC_HEAD = /^\s*(?:ARRANGEMENT\s+OF\s+(?:SECTIONS|CLAUSES|PARAGRAPHS|RULES|REGULATIONS|ARTICLES|ORDERS)|TABLE\s+OF\s+(?:PROVISIONS|CONTENTS)|CONTENTS|INDEX\s+OF\s+SECTIONS|SECTIONS)\s*$/i;
var RE_TOC_EXIT = /(?:BE\s+IT\s+ENACTED|ENACTED\s+by|^\s*An?\s+ACT\s+to\b|^\s*WHEREAS\b|^\s*PREAMBLE\b|in\s+exercise\s+of\s+the\s+(?:powers|functions)\s+conferred|(?:hereby\s+)?mak(?:e|es)\s+the\s+following\b|^\s*STATUTORY\s+RULES\b|enacts?\s+as\s+follows|\bThe\s+Lieutenant-Governor\b|\bGovernor\s+in\s+Council\b|\bwith\s+the\s+advice\s+of\s+the\s+Executive\s+Council\b|hereby\s+(?:make|makes|order|orders|prescribe|prescribes|issue|issues)\b|Now,?\s+therefore)/i;

/* Front matter that precedes the operative body. */
var RE_LONG_TITLE = /^\s*An?\s+(?:Act|Ordinance|Law|Bill)\s+to\b/i;
var RE_ENACTING   = /^\s*(?:BE\s+IT\s+ENACTED|ENACTED\s+by|Now,?\s+therefore|The\s+Parliament\s+of|Do\s+hereby\s+(?:issue|decree|promulgate))|enacts?\s+as\s+follows/i;
var RE_PREAMBLE   = /^\s*(?:PREAMBLE|WHEREAS\b|Having\s+reviewed\b|Having\s+perused\b)/i;

function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

/* A schedule-zone heading should keep the source's own word: a document may use
   SCHEDULE 1 and ANNEX A side by side. Falls back to the marker's cap. */
function zoneWord(line, fallback) {
  var m = String(line).match(/\b(SCHEDULES?|ANNEXURES?|ANNEXE?S?|APPENDIX|APPENDICES|ATTACHMENT|FORMS?)\b/i);
  if (!m) return fallback || 'SCHEDULE';
  var w = m[1].toUpperCase();
  if (/^ANNEXURE/.test(w)) return 'ANNEXURE';
  if (/^ANNEX/.test(w))    return 'ANNEX';
  if (/^SCHEDULE/.test(w)) return 'SCHEDULE';
  if (/^APPENDI/.test(w))  return 'APPENDIX';
  if (/^ATTACH/.test(w))   return 'ATTACHMENT';
  if (/^FORM/.test(w))     return 'FORM';
  return w;
}

function isNoise(line) {
  for (var i = 0; i < NOISE_RES.length; i++) if (NOISE_RES[i].test(line)) return true;
  return false;
}

/* ============ STAGE 0 · bilingual column split ============ */
/* Canadian federal / territorial consolidations print English and French in
   parallel columns. Mistral OCR reads a two-column page COLUMN-MAJOR: the whole
   English column, then the whole French column. So each page markdown is
   EN…EN FR…FR with exactly ONE switch point, and the job is to find it.

   Why a changepoint and not per-block language ID: the English column carries
   French « guillemet » glossary tags and the French column carries English
   "quoted" tags, so per-block ID misfires on short definition entries. A single
   split maximised over the whole page is driven by the long blocks and is
   immune to that. Cost is O(n) via a prefix sum: with fr-ness s_i, the split
   that best separates EN-first from FR-second is argmin of the prefix sum. */

var RE_IMG_MD   = /!\[[^\]]*\]\([^)]*\)/g;
var RE_GUILL    = /\u00AB[^\u00BB]{0,120}\u00BB/g;     // « … »
var RE_DQUOTE   = /[""\u201C\u201D"][^""\u201C\u201D"]{0,120}[""\u201C\u201D"]/g;

/* French evidence. Elisions are the single strongest cue in legal French. */
var FR_ELISION  = /\b(?:[ldjmntscç]|qu|jusqu|lorsqu|puisqu|quelqu)['\u2019]/gi;
var FR_ACCENT   = /[àâäçéèêëîïôöùûüÀÂÄÇÉÈÊËÎÏÔÖÙÛÜ]/g;
var FR_WORDS    = /\b(?:le|la|les|des|du|de|un|une|et|ou|qui|que|dans|pour|sur|aux|au|par|est|sont|ne|pas|plus|tout|toute|toutes|tous|selon|cas|présente|présent|loi|lois|article|articles|alinéa|paragraphe|règlement|règlements|partie|conformément|notamment|quiconque|doit|peut|peuvent|leur|leurs|ses|son|sa|cette|ces|avec|sans|entre|lorsque|ainsi|afin|être|avoir)\b/gi;

/* English evidence. */
var EN_WORDS    = /\b(?:the|of|and|or|a|an|in|to|is|are|was|were|that|this|these|those|which|must|may|shall|not|for|with|under|any|each|other|person|section|subsection|paragraph|Act|regulations?|means|includes|prescribed|following|purposes?|whether|before|after|their|its|his|her|be|been|has|have|had|if|as|on|at|from|by|but|does|do)\b/gi;

function countOf(s, re) { var m = s.match(re); return m ? m.length : 0; }

/* fr-ness of one block: positive = French, negative = English.
   Cross-language glossary tags are removed first, in BOTH directions, so an
   English definition ending in « employé » is not read as French and a French
   one ending in "employer" is not read as English. */
function frScore(block) {
  var t = String(block)
    .replace(RE_IMG_MD, ' ')
    .replace(RE_GUILL, ' ')
    .replace(RE_DQUOTE, ' ');

  var words = countOf(t, /[A-Za-zÀ-ÿ]{2,}/g);
  /* Only a block with no words at all is unscoreable. A one-word block still
     carries signal — "PARTIE" is French, "PART" is not — and forcing it to 0
     let a French group heading sit on a tie and get pulled into the EN half by
     the latest-minimum rule. */
  if (words < 1) return 0;

  var fr = 3 * countOf(t, FR_ELISION) + countOf(t, FR_ACCENT) + countOf(t, FR_WORDS);
  var en = countOf(t, EN_WORDS);
  return fr - en;
}

/* --- page furniture -------------------------------------------------------
   Running heads here are "…Act / PART 1 / Section 1 / LOI… / PARTIE 1 /
   Article 1" — the trailing number changes every page, so exact-match frequency
   dropping never fires. Normalise digits and roman numerals to '#', count the
   TEMPLATE across pages, and only drop inside the head/foot window so a real
   body line that happens to read "Section 9" survives. */
function furnitureKey(line) {
  return line.trim()
    .replace(/\s+/g, ' ')
    .replace(/\d+(?:[.\u2013\u2014-]\d+)*/g, '#')
    .replace(/#(?:\s*[\u2013\u2014-]\s*#)+/g, '#')
    .replace(/\b[ivxlcdm]{1,7}\b/gi, function (m) {
      return /^(?:i|in|is|it|mix|civil|did|dim|lid|mid|vim)$/i.test(m) ? m : '#';
    })
    .toUpperCase();
}


/* True when the non-blank neighbours on both sides of `li` are themselves
   furniture, and both lie inside the same head or foot window. */
function isSandwiched(p, li, count, minRepeat, head, foot) {
  var n = p.pos.indexOf(li);
  if (n <= 0 || n >= p.pos.length - 1) return false;
  /* Length cap. Running-head middle lines are short ("Interpretation",
     "Sections 3-3.2", "PARTIE 2"); real body text is not. Without this the
     window-free form of this rule will happily delete a sentence that merely
     happens to sit between two repeated lines — it ate the Yukon enacting
     formula, which then left stripTOC with no exit. */
  if ((p.lines[li] || '').trim().length > 60) return false;
  var a = furnitureKey(p.lines[p.pos[n - 1]]);
  var b = furnitureKey(p.lines[p.pos[n + 1]]);
  return (count[a] || 0) >= minRepeat && (count[b] || 0) >= minRepeat;
}

function dropPageFurniture(pageTexts, opts) {
  opts = opts || {};
  var head = opts.headWindow == null ? 8 : opts.headWindow;
  var foot = opts.footWindow == null ? 6 : opts.footWindow;
  /* NOT `minRepeat` — that name is taken by stage 1's dropRepeatedLines, and
     sharing it silently raises this threshold to 4. */
  var minRepeat = opts.furnitureMinRepeat == null ? 3 : opts.furnitureMinRepeat;

  var idx = pageTexts.map(function (p) {
    var lines = String(p).split('\n');
    var pos = [];                                    // indices of non-blank lines
    for (var i = 0; i < lines.length; i++) if (lines[i].trim()) pos.push(i);
    return { lines: lines, pos: pos };
  });

  /* count templates seen in a head or foot window */
  var count = Object.create(null);
  idx.forEach(function (p) {
    var seen = Object.create(null);
    p.pos.forEach(function (li, n) {
      /* Count everywhere, not just in the window: in column-major output the
         English footer sits mid-page, so a window-only count never sees it.
         The window still gates the low-threshold drop below. */
      var k = furnitureKey(p.lines[li]);
      if (!k || seen[k]) return;
      seen[k] = 1;
      count[k] = (count[k] || 0) + 1;
    });
  });

  var globalDrop = Math.max(minRepeat, Math.ceil(pageTexts.length * 0.6));

  var dropped = [];
  var out = idx.map(function (p) {
    var keep = [];
    p.lines.forEach(function (ln, li) {
      var t = ln.trim();
      if (!t) { keep.push(ln); return; }
      if (RE_IMG_MD.test(t) && !t.replace(RE_IMG_MD, '').trim()) { RE_IMG_MD.lastIndex = 0; dropped.push(t); return; }
      RE_IMG_MD.lastIndex = 0;
      if (/^[A-Za-z]$/.test(t)) { dropped.push(t); return; }          // stray chapter "c"
      if (/^page\s+[\divxlcdm]+$/i.test(t)) { dropped.push(t); return; }

      var n = p.pos.indexOf(li);
      var inWindow = n >= 0 && (n < head || n >= p.pos.length - foot);
      var c = count[furnitureKey(t)] || 0;
      /* In column-major output the English column's own footer lands in the
         MIDDLE of the page markdown, before the French column starts — so the
         window test alone misses it. A line repeating on most pages is
         furniture wherever it sits. */
      if (c >= globalDrop) { dropped.push(t); return; }
      if (inWindow && c >= minRepeat) { dropped.push(t); return; }
      /* Sandwich rule: Justice Laws running heads are three lines — act title,
         CURRENT heading, "Sections x-y". The middle one changes with the
         heading, so frequency never catches it. If a window line sits between
         two lines that were both dropped as furniture, it is furniture too. */
      /* Window-free: the French column's running head sits mid-page too, and
         once its constant lines go the varying middle line is left orphaned
         right on the EN|FR boundary. */
      if (isSandwiched(p, li, count, globalDrop, head, foot)) { dropped.push(t); return; }
      if (inWindow && isSandwiched(p, li, count, minRepeat, head, foot)) { dropped.push(t); return; }
      keep.push(ln);
    });
    return keep.join('\n');
  });

  return { pages: out, dropped: dropped };
}

/* --- the split ------------------------------------------------------------ */

function splitPage(pageText, opts) {
  opts = opts || {};
  var blocks = String(pageText).split(/\n\s*\n/).filter(function (b) { return b.trim(); });
  if (!blocks.length) return { en: '', fr: '', k: 0, margin: 0, blocks: 0 };

  var s = blocks.map(frScore);

  /* prefix[k] = sum of s[0..k-1]; the best EN|FR cut is argmin prefix */
  var prefix = [0], i;
  for (i = 0; i < s.length; i++) prefix.push(prefix[i] + s[i]);

  /* '<=' not '<': a run of unscoreable blocks (dot-leader TOC entries, bare
     headings) leaves the prefix flat across the true boundary. Taking the LAST
     minimum pushes the cut as late as possible, which biases toward keeping
     English — a stray French block is recoverable downstream, dropped English
     is not. */
  var k = 0, best = prefix[0];
  for (i = 1; i <= s.length; i++) if (prefix[i] <= best) { best = prefix[i]; k = i; }

  var en = blocks.slice(0, k), fr = blocks.slice(k);

  /* Safety net for pages Mistral happened to read row-major: drop any block
     left in the EN half that is emphatically French on its own. */
  var residual = [];
  if (opts.scrubResidual !== false) {
    en = en.filter(function (b, j) {
      var sc = s[j];
      if (sc >= 4 && sc > 0.30 * countOf(b, /[A-Za-zÀ-ÿ]{2,}/g)) { residual.push(b); return false; }
      return true;
    });
  }

  var enSum = 0, frSum = 0;
  for (i = 0; i < k; i++) enSum += s[i];
  for (i = k; i < s.length; i++) frSum += s[i];
  var margin = (k ? frSum / Math.max(1, s.length - k) : 0) - (k ? enSum / k : 0);

  return {
    en: en.join('\n\n'),
    fr: fr.join('\n\n'),
    k: k, blocks: blocks.length, margin: margin, residual: residual.length
  };
}


/* Rejoin a paragraph that runs across a page break: the tail block of one page
   does not close, and the head block of the next opens lower-case. Enumerated
   openers "(a)" / "(1)" start a new item and are never continuations. */
function joinAcrossPages(parts) {
  var out = [];
  for (var i = 0; i < parts.length; i++) {
    var cur = parts[i];
    if (!cur.trim()) continue;
    if (!out.length) { out.push(cur); continue; }
    var tb = out[out.length - 1].split(/\n\s*\n/);
    var hb = cur.split(/\n\s*\n/);
    var tail = (tb[tb.length - 1] || '').trim();
    var head = (hb[0] || '').trim();
    var open = tail && !/[.;:!?]\s*$/.test(tail) && !/^#/.test(tail);
    var cont = head && /^[a-z\u00AB]/.test(head) && !/^\([a-z0-9]{1,3}\)/i.test(head) && !/^#/.test(head);
    if (open && cont) {
      tb[tb.length - 1] = tail + ' ' + head;
      hb.shift();
      out[out.length - 1] = tb.join('\n\n');
      cur = hb.join('\n\n');
    }
    if (cur.trim()) out.push(cur);
  }
  return out.join('\n\n');
}

/* Canadian bilingual consolidation markers — checked on RAW text, before the
   furniture drop removes the footer that carries most of them. */
var RE_CA_MARK = /UNOFFICIAL CONSOLIDATION OF THE STATUTES|CODIFICATION NON OFFICIELLE|laws-lois\.justice\.gc\.ca|lois-laws\.justice\.gc\.ca|Justice Laws Website|Site Web de la l\u00E9gislation|Minister of Justice at the following address|Current to \w+ \d{1,2}, \d{4}|Last amended on \w+ \d{1,2}, \d{4}|\bR\.S\.[A-Z]{0,2}\.?,?\s*\(?\d{4}\)?,?\s*(?:c|ch)\.|\bL\.R\.[A-Z]{0,2}\.?,?\s*\(?\d{4}\)?,?\s*ch\.|\b[SL]Y\s+\d{4},?\s*(?:c|ch)\.|Commissioner in Executive Council|Lieutenant Governor in Council|Commissioner of (?:Yukon|Nunavut)|TABLE OF PROVISIONS/i;

/* Public entry point.
   input : Mistral response, { pages:[…] }, an array of pages, or raw markdown
   opts  : { keep:'en'|'fr', scrubResidual, headWindow, footWindow, minRepeat }
   return: { text, meta } */
function splitBilingual(input, opts) {
  opts = opts || {};
  var keep = opts.keep === 'fr' ? 'fr' : 'en';

  var pages;
  if (input == null) pages = [];
  else if (typeof input === 'string') pages = [input];
  else if (Array.isArray(input)) pages = input;
  else if (Array.isArray(input.pages)) pages = input.pages;
  else pages = [input];

  var texts = pages.map(function (p) {
    if (typeof p === 'string') return p;
    return (p && (p.markdown || p.text || p.extractedText || p.content)) || '';
  });

  var raw = texts.join('\n');
