     5-13-201  5-901  1-50-8  45-30-1  74-4E-1  33.1-12-01-01  437-003-3060
     2C:11-3  9:2800  265:79   5/3-106   22\u20133211   9VAC25-610-10
   with an optional agency prefix (WAC, ATCP, R, CSR, VAC) and an optional
   \u00A7 / Sec. / SEC. / Section / Rule word.                                       */
var US_TOKEN =
  '(?:\\.\\d{1,4}|\\d{1,5}[A-Za-z]{0,5}\\d{0,4})(?:[.\\-\\u2013:\\/][0-9A-Za-z]{1,7})*';
var US_WORD   = '(?:SECTION|Section|SEC\\.|Sec\\.|RULE|Rule|REGULATION|Regulation|Reg\\.)';
var US_AGENCY = '(?:[A-Z]{1,6})';
/* Agency codes may carry a leading volume number: "10 CSR 40-10.010",
   "310 CMR 75.01", "WAC 296-37-510", "R 325.77101", "ATCP 29.01". When present
   the whole printed citation is the marker, per articleStyle:'source'. */
var US_STOP = /^(?:THE|AND|FOR|NOT|ALL|ANY|SEE|PER|BUT|OUR|ITS|NEW|ONE|TWO|SIX|TEN|WAS|ARE|MAY)$/;
var RE_US_LEAD = new RegExp(
  '^\\s*(?:\\u00A7\\u00A7?\\s*)?(?:' + US_WORD + '\\s+)?' +
  '((?:\\d{1,3}\\s+)?(?:' + US_AGENCY + '\\s+)?' + US_TOKEN + ')\\s*([.:]?)\\s+(\\S.*)$');
/* parenthesised enumerations are NEVER headings - they are content */
var RE_US_ENUM = /^\s*\(\s*(?:[a-zA-Z]{1,4}|\d{1,3}|[ivxlcdmIVXLCDM]{1,6})\s*\)/;
/* roman / letter outline heads used in permits: "I COVERAGE", "A. Permit Authority" */
var RE_US_ROMAN = /^\s*([IVXLCDM]{1,5}|[A-Z])\s*[.:]?\s+([A-Z][^\n]{1,90})$/;
var MDH_TAG = '\u0001MDH\u0001';

/* When Mistral emits real markdown headings it has already told us where the
   article boundaries are. In that case the deeper printed numbering (1.1, 1.2,
   2.1 ...) is CONTENT of the heading above it, not a heading of its own - the
   article is the shallowest titled level, and everything under it is contenu.
   Only trust this when the headings actually span the document; a lone title
   heading must not suppress ordinary section detection. */
/* Many state administrative codes number the top level "N.0" and its children
   "N.M" / "N.M.P" (Delaware, Minnesota, and others). When that plan is in use
   the article level is decided by the NUMBER, not by markdown - so a document
   whose headings Mistral failed to mark up still segments correctly. */
var RE_ZERO_TOP = new RegExp('^[ \\t]*(?:' + MDH_TAG + '\\d\\u0001)?(\\d{1,3})\\.0(?:[ \\t]|$)');
