  var L = text.split('\n'), seen = {}, n = 0, i, m;
  for (i = 0; i < L.length; i++) {
    m = L[i].match(RE_ZERO_TOP);
    if (m && !seen[m[1]]) { seen[m[1]] = 1; n++; }
  }
  return n >= 2;
}

/* The article level is whichever enumeration appears FIRST/shallowest, and it
   holds until the next marker at that same level. Three plans occur:
     zeroTop : "1.0 / 2.0" top, "1.1 / 1.1.1" children      (Delaware, Minnesota)
     depth 1 : "1. / 2." top, "1.1 / 1.1.1.1" children      (Georgia IGP, permits)
     depth 2 : "21.15 / 552.001" leaf, no shallower level   (CFR, Texas)
   Only dotted-decimal tokens take part; "5-901" or "WAC 296-37-510" are not
   outlines and are judged on their own. */
var RE_OUTLINE_TOK = /^[ \t]*(?:\u00A7\u00A7?\s*)?(?:SECTION|Section|SEC\.|Sec\.|RULE|Rule)?[ \t]*(\d{1,4}(?:\.\d{1,4})*)[ \t]*[.:]?[ \t]+\S/;
function detectOutlinePlan(text) {
  if (detectZeroTopOutline(text)) return { kind: 'zeroTop' };
  var L = text.split('\n'), byDepth = {}, i, m, d, ln;
  for (i = 0; i < L.length; i++) {
    ln = L[i];
    if (ln.indexOf(MDH_TAG) === 0) ln = ln.replace(/^\u0001MDH\u0001\d\u0001/, '');
    m = ln.match(RE_OUTLINE_TOK); if (!m) continue;
    d = m[1].split('.').length;
