}

function mdIsAuthoritative(text) {
  var L = text.split('\n'), n = 0, last = -1, i;
  for (i = 0; i < L.length; i++) if (L[i].indexOf(MDH_TAG) === 0) { n++; last = i; }
  if (n < 2) return false;
  return last > L.length * 0.35;
}

/* A heading is <marker> + <short title>, optionally followed by run-in body
   text that begins with an enumeration. Returns null for ordinary prose. */
function usHeadingParts(line, plan) {
  if (RE_US_ENUM.test(line)) return null;
  var m = line.match(RE_US_LEAD);
  if (!m) return null;
  var tok = m[1].replace(/\s+/g, ' ').trim(), sep = m[2] || '', rest = m[3].trim();
  var ag = tok.match(/\b([A-Z]{2,6})\b/);
  if (ag && US_STOP.test(ag[1])) return null;

  var numPart = tok.split(/\s+/).pop();
  var pure = /^\d{1,4}(?:\.\d{1,4})*$/.test(numPart), planOK = false;
  if (plan && pure) {
    if (plan.kind === 'zeroTop') {
      if (!/^\d{1,3}\.0$/.test(numPart)) return null;
    } else if (plan.kind === 'depth') {
      if (numPart.split('.').length !== plan.depth) return null;
    }
    planOK = true;                       /* the plan vouches for this marker */
  }

  /* run-in body: "(a) ..." first, then a plain following sentence */
  var title = rest, body = '';
  var ri = rest.match(/^(.{2,120}?[.?:])\s+(\([a-zA-Z0-9]{1,4}\).*)$/);
  if (!ri) ri = rest.match(/^(.{2,120}?[.?])\s+(\S.{25,})$/);
  if (ri) { title = ri[1]; body = ri[2]; }

  /* Without a plan a bare number is ambiguous ("1. Applicability" is a heading,
     "1. The permittee shall retain copies," is a list item), so keep the guard.
     With a plan the numbering already settled it. */
  if (!planOK && !/[.\-:\/\u2013]/.test(numPart)) {
    if (title.length > 90 || /[,;]$/.test(title)) return null;
    if (!/^[A-Z"\u201C]/.test(title)) return null;
  }
  if (title.length > 220) return null;
  /* keep the printed dot on a bare top-level number: "1." not "1" */
  if (/^\d+$/.test(numPart) && sep.indexOf('.') >= 0) tok = tok + '.';
  return { marker: tok, title: title, body: body };
}

/* Mistral emits real markdown headings ("# PART I:", "## A. DISCHARGE ...").
   That is authoritative structure, but cleanText's stripMarkdown deletes the
   hashes, so tag them first. Runs only when the pre-probe says US. */
function tagMdHeadings(text) {
  return text.replace(/^[ \t]{0,3}(#{1,6})[ \t]+(\S.*?)[ \t]*#*[ \t]*$/gm,
    function (_, h, t) { return MDH_TAG + h.length + '\u0001' + t; });
}

/* A lone enumeration marker orphaned on its own line by a PDF column break
   ("(v)\n\nhydrochlorofluorocarbon-142b.") belongs with the line beneath it. */
function joinOrphanEnum(text) {
  var L = text.split('\n'), out = [], i, j;
  for (i = 0; i < L.length; i++) {
    if (/^\s*\([a-zA-Z0-9]{1,4}\)\s*$/.test(L[i])) {
      for (j = i + 1; j < L.length && !L[j].trim(); j++) {}
      if (j < L.length && !RE_US_ENUM.test(L[j]) && !usHeadingParts(L[j])) {
        out.push(L[i].trim() + ' ' + L[j].trim()); i = j; continue;
      }
    }
    out.push(L[i]);
  }
  return out.join('\n');
}


/* "Chapter 1\n\nMotor Carriers" - US rule chapters print the number and the
   title on separate lines. Fold the orphan title back onto its heading. */
function foldGroupTitle(text) {
  var L = text.split('\n'), out = [], i, j, m;
  var GRP = /^\s*(TITLE|SUBTITLE|PART|SUBPART|CHAPTER|SUBCHAPTER|DIVISION|ARTICLE|SERIES)\s+([0-9A-Za-z.\-]{1,14}|[IVXLCDM]{1,6})\s*[.:]?\s*$/i;
  for (i = 0; i < L.length; i++) {
    m = L[i].match(GRP);
    if (!m) { out.push(L[i]); continue; }
    for (j = i + 1; j < L.length && !L[j].trim(); j++) {}
    var nx = j < L.length ? L[j].trim() : '';
    if (nx && nx.length <= 80 && !GRP.test(nx) && !RE_US_ENUM.test(nx) &&
        !usHeadingParts(nx) && /^[A-Z\u201C"]/.test(nx) && !/[,;:]$/.test(nx)) {
      out.push(L[i].replace(/\s*$/, '') + '  ' + nx); i = j; continue;
    }
    out.push(L[i]);
  }
  return out.join('\n');
}

/* ---- US fix: undesignated center heads ----
   In CFR/state codes a bare Title-Case or CAPS line with no marker and no
   trailing period, standing between two section headings, is a real structural
   level ("Code Structure", "Numbering", "Effective Date Statement"). Tag it so
   the marker table can catch it; the "next line is a section" test is what
   keeps this from swallowing ordinary prose. */
var CENTERHEAD_TAG = '\u0001CH\u0001';
var RE_US_SEC_LINE = /^\s*(?:\u00A7\u00A7?|SECTION|Section|SEC\.|Sec\.)\s*\d/;
function markCenterHeads(text) {
  var L = text.split('\n'), out = [], i, t, nxt, j;
  for (i = 0; i < L.length; i++) {
    t = L[i].trim();
    if (!t || t.length > 60 || /[.;:,]$/.test(t) || RE_US_SEC_LINE.test(t) ||
        /^[\d(\u00A7]/.test(t) || /^(?:TITLE|SUBTITLE|PART|SUBPART|CHAPTER|SUBCHAPTER|DIVISION|APPENDIX)\b/i.test(t) ||
        !/^[A-Z]/.test(t) || t.split(/\s+/).length > 6) { out.push(L[i]); continue; }
    if (i > 0 && L[i - 1].trim()) { out.push(L[i]); continue; }   // must stand alone
    nxt = '';
    for (j = i + 1; j < L.length; j++) { if (L[j].trim()) { nxt = L[j].trim(); break; } }
    if (RE_US_SEC_LINE.test(nxt)) out.push(CENTERHEAD_TAG + t);
    else out.push(L[i]);
