  return out.join('\n');
}

/* ---- US fix: unheaded tables of contents ----
   A US TOC has no "TABLE OF CONTENTS" banner, so RE_TOC_HEAD cannot see it.
   Its signature is structural: a run of section-heading lines with no prose
   between them. Case is NOT a discriminator - Texas prints both TOC and body
   in caps. Drop a run of >= minRun such lines when those same markers recur
   later in the document. */
