    t = L[i].trim(); if (!t) continue;
    var m = t.match(re); if (!m) continue;
    /* a TOC entry is a heading only - no sentence body after the title */
    if (/\(\w{1,3}\)/.test(m[2]) || m[2].length > 150) continue;
    run = [i]; marks = [m[1]];
    for (j = i + 1; j < L.length; j++) {
      var u = L[j].trim(); if (!u) continue;
      var m2 = u.match(re);
