function classifyDoc(text) {
  var head = text.split('\n').slice(0, 160).join('\n');
  var scores = { primary: 1 }, i, s;
  for (i = 0; i < CLASS_SIGNALS.length; i++) {
    s = CLASS_SIGNALS[i];
    if (s.re.test(head) || (s.w >= 7 && s.re.test(text.slice(0, 20000)))) {
      scores[s.cls] = (scores[s.cls] || 0) + s.w;
