  { d: 'US', w: 4, re: /\b(?:Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|Delaware|Florida|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|Louisiana|Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|Missouri|Montana|Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|South Dakota|Tennessee|Texas|Utah|Vermont|Virginia|Washington|West Virginia|Wisconsin|Wyoming|District of Columbia|Puerto Rico)\b/ },
  { d: 'US', w: 4, re: /\bNPDES\b|\bEnvironmental Protection Agency\b|\bU\.?S\.? EPA\b|\bOSHA\b|\bDepartment of Transportation\b|\bSecretary of State\b/i },
  { d: 'CA', w: 8, re: /UNOFFICIAL CONSOLIDATION OF THE STATUTES|CODIFICATION NON OFFICIELLE|Justice Laws Website|Site Web de la l\u00E9gislation/i },
  { d: 'CA', w: 6, re: /(?:^|[^.A-Z])(?:R\.S\.[A-Z]{1,2}\.|S\.[A-Z]{1,2}\.)\s*\d{4}\s*,?\s*(?:c|ch)\.|\b[SL]Y\s+\d{4},?\s*(?:c|ch)\.\s*\d+/ },
  { d: 'CA', w: 6, re: /\bCommissioner in Executive Council\b|\bLieutenant Governor in Council\b|\bCommissioner of (?:Yukon|Nunavut)\b/i },
  { d: 'CA', w: 3, re: /\b(?:Yukon|Nunavut|Northwest Territories|Saskatchewan|Manitoba|Alberta|British Columbia|Ontario|Qu\u00E9bec|New Brunswick|Nova Scotia|Newfoundland and Labrador|Prince Edward Island)\b/ }
];

function classifyDialect(text) {
  var probe = text.slice(0, 40000), scores = {}, i;
  for (i = 0; i < DIALECT_SIGNALS.length; i++) {
    if (DIALECT_SIGNALS[i].re.test(probe)) {
      scores[DIALECT_SIGNALS[i].d] = (scores[DIALECT_SIGNALS[i].d] || 0) + DIALECT_SIGNALS[i].w;
    }
  }
  var best = null, bv = 0;
  for (var k in scores) if (scores[k] > bv) { bv = scores[k]; best = k; }
  return { dialect: best, scores: scores };
}

/* Vol. I 3.1: for subsidiary legislation the leaf unit is set by the instrument
   title, not the jurisdiction. Regulations -> regulation, Order -> article,
   Rules -> rule. */
function detectLeafUnit(text, doc_class) {
  var head = text.split('\n').slice(0, 80).join('\n');
  var score = { Regulation: 0, Rule: 0, Article: 0 };
  var re = /(^|[^A-Za-z])(STATUTORY\s+)?(Regulations|Rules|Order)\s+(?:19|20)\d{2}\b/gi, m;
  while ((m = re.exec(head)) !== null) {
    if (m[2]) continue;                       // "STATUTORY RULES 2025" = series label
    var w = m[3].toLowerCase();
    if (w === 'regulations') score.Regulation++;
    else if (w === 'rules')  score.Rule++;
    else if (w === 'order')  score.Article++;
  }
  var best = null, bv = 0;
  for (var k in score) if (score[k] > bv) { bv = score[k]; best = k; }
  return best;
}

/* class + dialect -> family */
function pickFamily(doc_class, dialect, text) {
  if (doc_class === 'standard')    return 'en_standards_clause';
  if (doc_class === 'judgment')    return 'en_judgment';
  if (doc_class === 'regulatory')  return 'en_regulatory';
  if (doc_class === 'court_rules') return 'en_order_rule';
  if (doc_class === 'constitution') return 'en_constitution';
  if (dialect === 'US') return 'us_statute';
  if (dialect === 'AE') return 'en_gulf_article';
  if (dialect === 'ZA') return 'en_sa_gazette';
  if (dialect === 'IN' || dialect === 'NG') return 'en_commonwealth_legacy';
  if (dialect === 'UK' || dialect === 'IE' || dialect === 'AU' || dialect === 'HK' ||
      dialect === 'CA') return 'en_westminster';
  /* structural fallback — Vol. I 4: tie-break to en_westminster, the safe superset */
  var arts = (text.match(/^\s*Article\s*[\(\d]/gim) || []).length;
  var secs = (text.match(/^\s*\d{1,4}[A-Z]{0,3}\.?\s+[A-Z]/gm) || []).length;
  var groups = (text.match(/^\s*(?:PART|CHAPTER|SCHEDULE|Division)\b/gim) || []).length;
  if (arts >= 3 && arts > secs) return 'en_gulf_article';
  if (secs >= 3 || (secs >= 1 && groups >= 1)) return 'en_westminster';
  if (doc_class === 'primary' || doc_class === 'subsidiary') return 'en_westminster';
  return 'generic';
}

/* ---------- Stage 2c: dialect strippers ---------- */


/* Justice Laws prints the section heading as a MARGINAL note on the line above
   the section number, so the number line carries no title and `article` comes
   out bare ("4" instead of "4 Right to access to records"). Fold a marginal
   note onto the section line it belongs to. Section level only — a note above a
   bare subsection "(2)" has no marker to attach to and is left alone. */
var RE_CA_SECNUM = /^\s*(\d{1,4}(?:\.\d{1,3}){0,2}[A-Z]{0,2})\s+(\(\d{1,3}[A-Za-z]?\)\s*.*)$/;

function foldMarginalNotes(text) {
  var lines = text.split('\n'), out = [], i, note = null;
  for (i = 0; i < lines.length; i++) {
    var t = lines[i].trim();
    if (!t) { out.push(lines[i]); continue; }   // keep the note pending across the gap

    var m = t.match(RE_CA_SECNUM);
    if (m && note) {                       // note + "4 (1) Subject to …"
      out.push(m[1] + ' ' + note);         // -> "4 Right to access to records"
      out.push(m[2]);                      // -> "(1) Subject to …"
      note = null;
      continue;
    }
    if (note) { out.push(note); note = null; }

    /* candidate note: short, sentence-less, opens upper-case, has lower-case */
    if (t.length <= 90 && /^[A-Z\u201C"]/.test(t) && /[a-z]/.test(t) &&
        !/[.;:,]$/.test(t) && !/^\(/.test(t) && !RE_GROUP_HEAD.test(t)) {
      var j = i + 1;
      while (j < lines.length && !lines[j].trim()) j++;   // Mistral blank-line gap
      if (RE_CA_SECNUM.test((lines[j] || '').trim())) { note = t; continue; }
    }
    out.push(lines[i]);
  }
  if (note) out.push(note);
  return out.join('\n');
}


/* Last line of defence for the English-only contract. Stage 0 removes the
   French COLUMN; this removes anything French that survived — an orphaned
   fragment left by a bad column split, or a French heading pulled across on a
   tie. It deliberately does NOT touch « guillemet » glossary tags: frScore
   blanks those before scoring, so an English definition citing « employeur »
   scores English and is kept, exactly as it is printed in the Act. */
function dropFrenchLines(text) {
  return text.split('\n').filter(function (l) {
    var t = l.trim();
    if (!t) return true;
    var bare = t.replace(/\u00AB[^\u00BB]{0,120}\u00BB/g, ' ');
    var words = (bare.match(/[A-Za-z\u00C0-\u00FF]{2,}/g) || []).length;
    /* An orphaned glossary tag — "« employé »", or "électronique »" left behind
       when a wrapped line was split. Never standalone English; drop it. The
       same tag inside a real definition line survives, because that line has
       plenty of words outside the span. */
    if (/\u00BB/.test(t) && words < 3) return false;
    if (words < 3) return true;                 // too short to judge safely
    var s = frScore(t);
    return !(s >= 3 && s > 0.25 * words);       // clearly French -> drop
  }).join('\n');
}

/* "1 Purposes of Act (Objet de la loi)" -> "1 Purposes of Act".
   Only fires when the parenthetical itself scores French, so English asides
   like "(Canada)" or "(other than a young person)" survive. */
function dropFrenchParenTail(text) {
  return text.split('\n').map(function (l) {
    return l.replace(/\s*\(([^()]{3,80})\)\s*$/, function (whole, inner) {
      return frScore(inner) > 0 ? '' : whole;
    });
  }).join('\n');
}

function applyStrippers(text, dialect, doc_class, opts) {
  if (dialect === 'CA') text = foldMarginalNotes(text);
  if (dialect === 'US') {
    text = joinOrphanEnum(text);
    text = foldGroupTitle(text);
    if (opts && opts.stripUSTOC !== false) text = stripUSTOC(text, (opts && opts.usTocMinRun) || 4);
    if (opts && opts.centerHeads !== false) text = markCenterHeads(text);
  }
  var lines = text.split('\n'), i, l;
  for (i = 0; i < lines.length; i++) {
    l = lines[i];
    if (dialect === 'HK') { l = l.replace(STRIPPERS.hk_flag, '').replace(STRIPPERS.hk_source, ''); }
    if (dialect === 'UK') { l = l.replace(STRIPPERS.uk_fmark, ''); }
    if (dialect === 'IE') { l = l.replace(STRIPPERS.ie_fmark, ''); }
    if (dialect === 'ZA') { l = l.replace(STRIPPERS.za_edit, ''); }
    if (dialect === 'CA') {
      if (opts && opts.stripGlossTags) l = l.replace(STRIPPERS.ca_gloss, '');
      if (STRIPPERS.ca_amend.test(l)) l = '';
    }
    if (dialect === 'IN' || dialect === 'NG' || doc_class === 'regulatory') {
      l = l.replace(STRIPPERS.in_bracket_open, '$1').replace(/\]/g, function (m, off, s) {
        return /\[/.test(s.slice(0, off)) ? '' : m;
      });
      l = l.replace(STRIPPERS.in_omitted, '');
    }
    lines[i] = l.replace(/\s{2,}/g, ' ').replace(/\s+$/, '');
  }
  return lines.join('\n');
}

